                asset_type == "dashboard",
            ),
        }
        buf = BytesIO()
        with ZipFile(buf, "w") as bundle:
            with bundle.open("export/metadata.yaml", "w") as fp:
                fp.write(yaml.safe_dump(metadata_files[asset_type]).encode())

            for folder, (
                assets,
                default_config,
                should_have_default,
            ) in asset_configs.items():
